	// every reader accepts it whatever prefix it skips, and the trailer never
	// lands after prose or a kept "#" line.
	if trailerLines, otherLines, _ := countTrailerBlock(lines[start:], ""); separated && trailerLines > 0 && otherLines == 0 {
